export default Viewport;

import { Vector3 } from 'three';

export enum ToolType {
  SELECT = 'SELECT',
  PUSH_PULL = 'PUSH_PULL', // 推拉工具 (調整長寬高)
  ROTATE = 'ROTATE', // 旋轉工具
  DRAW_LINE = 'DRAW_LINE', // 直線
  DRAW_RECT = 'DRAW_RECT', // 矩形
  DRAW_CIRCLE = 'DRAW_CIRCLE', // 圓形
  MEASURE = 'MEASURE', // 測量/標註 (含輔助線)
}

export type ShapeType = 'solid' | 'flat' | 'dimension'; // 立體 | 平面 | 標註

export type TransformMode = 'translate' | 'scale'; // 移動或縮放

export interface IPoint {
  x: number;
  y: number;
  z: number;
}

export interface ILayer {
  id: string;
  name: string;
  visible: boolean;
  locked: boolean;
}

export interface IShape {
  id: string;
  groupId?: string; // ID for grouping multiple objects
  layerId: string; // ID of the layer this shape belongs to
  type: ShapeType;
  points: IPoint[]; // 地面上的 2D 輪廓點
  height: number;
  color: string;
  position: [number, number, number];
  rotation: [number, number, number]; // Euler angles (x, y, z)
  scale: [number, number, number]; // 新增縮放比例
  name: string;
}

export interface IGuideLine {
  id: string;
  points: [[number, number, number], [number, number, number]]; // Two points defining the infinite line
}

export interface ISceneState {
  shapes: IShape[];
  layers: ILayer[];
  selectedId: string | null;
  tool: ToolType;
  gridSize: number;
}

// AI Generation Types
export interface AIGeneratedItem {
  name: string;
  width: number;
  depth: number;
  height: number;
  color: string;
  x: number;
  z: number;
}

import React, { createContext, useContext, useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { IShape, ToolType, IPoint, TransformMode, ILayer, IGuideLine } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

type UnitType = 'm' | 'cm';

interface AppContextType {
  // Project Info
  projectName: string;
  setProjectName: (name: string) => void;

  // Shapes
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void;
  removeShape: (id: string) => void;
  removeSelected: () => void;
  replaceShapes: (idsToRemove: string[], newShapes: IShape[]) => void;
  copySelected: () => void;
  groupSelected: () => void;
  ungroupSelected: () => void;

  // Guide Lines
  guideLines: IGuideLine[];
  addGuideLine: (line: IGuideLine) => void;
  clearGuideLines: () => void;

  // Layers
  layers: ILayer[];
  activeLayerId: string;
  setActiveLayerId: (id: string) => void;
  addLayer: (name: string) => void;
