const Protractor: React.FC<{ 
    position: THREE.Vector3; 
    axis: THREE.Vector3; 
    startVector?: THREE.Vector3; 
    currentVector?: THREE.Vector3;
    angle?: number;
    active: boolean; 
}> = ({ position, axis, startVector, currentVector, angle = 0, active }) => {

    // Determine Color based on Axis (SketchUp style)
    let color = 'black';
    if (Math.abs(axis.y) > 0.9) color = '#3b82f6'; // Blue (Y) - Ground
    else if (Math.abs(axis.x) > 0.9) color = '#ef4444'; // Red (X)
    else if (Math.abs(axis.z) > 0.9) color = '#22c55e'; // Green (Z)

    // Create Orientation Quaternion
    const quaternion = useMemo(() => {
        const q = new THREE.Quaternion();
        q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axis.clone().normalize());
        return q;
    }, [axis]);

    // Sector Geometry for filled area
    const sectorGeometry = useMemo(() => {
        if (!active || Math.abs(angle) < 0.01) return null;
        // The circle starts at 3 o'clock (positive X). We need to align it with startVector.
        return <circleGeometry args={[0.9, 32, 0, Math.abs(angle)]} />;
    }, [angle, active]);

    // Calculate rotation for the sector to match startVector
    const sectorRotation = useMemo(() => {
        if (!startVector) return new THREE.Euler(-Math.PI/2, 0, 0);

        // Transform startVector to local space of the protractor (which is aligned to axis)
        const localStart = startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize();
        let baseAngle = Math.atan2(localStart.z, localStart.x); // In local space (Y is Up), logic corresponds to X-Z plane on the protractor surface

        // However, the circle geometry lies on XY plane, then rotated -90 X. 
        // So local X is X, local Y becomes -Z.
        // Actually simplest is: geometry on XY plane. We rotate X to -90.
        // Then we rotate Z to match start.

        // Correction: The mesh is rotated [-PI/2, 0, 0].
        // Local coordinates: x->x, y->z, z->-y.
        // Let's rely on standard rotation.

        // Just use `angleTo` relative to a reference for simplicity or construct a lookAt.
        // Re-derivation:
        // We want the sector start (theta=0) to align with startVector.
        // In the local frame of the protractor (Y aligned with axis), the startVector is on the XZ plane.
        // The circleGeometry is created on XY plane. 
        // We rotate it -90 on X so it's on XZ plane.
        // Now (1,0,0) is (1,0,0). (0,1,0) became (0,0,1).

        // So we just need the angle of startVector in the local XZ plane.
        const angleOffset = Math.atan2(localStart.z, localStart.x); // -PI to PI

        // If angle is negative, we might need to flip or rotate differently?
        // CircleGeometry fills counter-clockwise.
        // If our actual rotation is negative (clockwise), we rotate the sector starting point?
        // Actually, if angle is negative, we should probably start at `angleOffset + angle` and fill positive `-angle`.
        // But for visual simplicity, let's just rotate the container group.

        const rotationY = -angleOffset; // atan2 is counter-clockwise from X. Threejs Y rotation is counter-clockwise.

        // If angle is negative (CW), we want the sector to appear "behind" the start line.
        // Or we draw the sector from (start + angle) to (start).

        let finalStartAngle = -angleOffset;
        if (angle < 0) {
             finalStartAngle = -angleOffset - Math.abs(angle);
        }

        return new THREE.Euler(-Math.PI/2, 0, finalStartAngle); // Rotate flat then rotate around center
    }, [startVector, quaternion, angle]);

    return (
        <group position={position} quaternion={quaternion}>
            {/* Outer Ring */}
            <mesh rotation={[-Math.PI/2, 0, 0]}>
                <ringGeometry args={[0.85, 0.9, 64]} />
                <meshBasicMaterial color={color} opacity={0.8} transparent side={THREE.DoubleSide} />
            </mesh>

            {/* Inner Transparent Fill */}
            <mesh rotation={[-Math.PI/2, 0, 0]}>
                <circleGeometry args={[0.85, 64]} />
                <meshBasicMaterial color={color} opacity={0.1} transparent side={THREE.DoubleSide} />
            </mesh>

            {/* Ticks */}
            {Array.from({length: 24}).map((_, i) => {
                const isMajor = i % 6 === 0; // 90 degrees
                const len = isMajor ? 0.2 : 0.1;
                return (
                    <group key={i} rotation={[0, (i * Math.PI * 2) / 24, 0]}>
                        <SimpleLine points={[new THREE.Vector3(0,0,0.85 - len), new THREE.Vector3(0,0,0.85)]} color={color} opacity={isMajor ? 1 : 0.5} />
                    </group>
                )
            })}

            {/* Filled Sector (Visualizing the angle) */}
            {active && startVector && Math.abs(angle) > 0.01 && (
                 <mesh rotation={sectorRotation}>
                    <circleGeometry args={[0.85, 32, 0, Math.abs(angle)]} />
                    <meshBasicMaterial color={color} opacity={0.3} transparent side={THREE.DoubleSide} />
                 </mesh>
            )}

            {/* Start Line */}
            {startVector && (
                 <SimpleLine points={[new THREE.Vector3(0,0,0), startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="black" lineWidth={2} />
            )}

            {/* Current Line */}
            {active && currentVector && (
                 <SimpleLine points={[new THREE.Vector3(0,0,0), currentVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="red" lineWidth={2} dashed />
            )}

            {/* Angle Text */}
            {active && Math.abs(angle) > 0.01 && (
                <Billboard position={[0, 0.5, 0]}>
                    <Text
                        fontSize={0.3}
                        color="white"
                        outlineWidth={0.02}
                        outlineColor={color}
                        backgroundColor="rgba(0,0,0,0.5)"
                        padding={0.05}
                    >
                        {(angle * 180 / Math.PI).toFixed(1)}°
                    </Text>
                </Billboard>
            )}
        </group>
    );
};

