        case 'vertex': 
            displayType = '節點 (Node)'; 
            bgColor = 'bg-emerald-600'; 
            break;
        case 'endpoint': 
            displayType = '端點 (Endpoint)'; 
            bgColor = 'bg-emerald-600'; 
            break;
        case 'midpoint': 
            displayType = '中點 (Midpoint)'; 
            bgColor = 'bg-cyan-600'; 
            break;
