const MemoizedOrbitControls = React.memo((props: any) => <OrbitControls {...props} makeDefault />);

const ShapeRenderer: React.FC<ShapeRendererProps> = React.memo(({ shape, isSelected, onSelect, setShapeRef }) => {
    const meshRef = useRef<THREE.Group>(null);

    useEffect(() => {
        if (setShapeRef && meshRef.current) setShapeRef(meshRef.current);
    }, [setShapeRef]);

    const geometry = useMemo(() => {
        const s = createThreeShape(shape.points);
        if (shape.type === 'solid' || shape.height > 0) {
            return new THREE.ExtrudeGeometry(s, { depth: shape.height, bevelEnabled: false });
        }
        return new THREE.ShapeGeometry(s);
    }, [shape.points, shape.height, shape.type]);

    return (
        <group position={shape.position} rotation={shape.rotation} scale={shape.scale} ref={meshRef} userData={{ isShape: true, id: shape.id }} onClick={onSelect}>
             <mesh rotation={[Math.PI/2, 0, 0]} castShadow receiveShadow>
                <primitive object={geometry} />
                <meshStandardMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
             </mesh>
             {isSelected && <group rotation={[Math.PI/2, 0, 0]}><Edges geometry={new THREE.EdgesGeometry(geometry)} color="white" /></group>}
        </group>
    );
});

const InteractionLayer = (props: any) => null;
const AlignmentLinesRenderer = ({ lines }: { lines: AlignmentLine[] }) => null;
const GuideLinesRenderer = ({ lines }: { lines: IGuideLine[] }) => null;

const SelectionGizmo = ({ setDragging }: { setDragging: (d: boolean) => void }) => {
    const { selectedIds, shapes, updateShape, tool, transformMode } = useApp();
    const { scene } = useThree();
    const selectedObj = useMemo(() => {
        if (selectedIds.length !== 1) return undefined;
        let found: THREE.Object3D | undefined;
        scene.traverse((o) => { if (o.userData?.id === selectedIds[0]) found = o; });
        return found;
    }, [selectedIds, scene, shapes]);

    if (tool !== ToolType.SELECT || !selectedObj) return null;
    return <TransformControls object={selectedObj} mode={transformMode} onDraggingChanged={(e) => setDragging(e.value)} onChange={() => {
        if (selectedObj) updateShape(selectedIds[0], { position: selectedObj.position.toArray(), rotation: [selectedObj.rotation.x, selectedObj.rotation.y, selectedObj.rotation.z], scale: selectedObj.scale.toArray() });
    }} />;
};

const CameraHandler = ({ view, onFinished }: { view: string | null, onFinished: () => void }) => {
    const { camera } = useThree();
    useEffect(() => {
        if (view) {
             const offset = 10;
             if (view === 'top') camera.position.set(0, offset, 0);
             else if (view === 'front') camera.position.set(0, 0, offset);
             else if (view === 'right') camera.position.set(offset, 0, 0);
             else if (view === 'left') camera.position.set(-offset, 0, 0);
             else if (view === 'bottom') camera.position.set(0, -offset, 0);
             camera.lookAt(0, 0, 0);
             onFinished();
        }
    }, [view, camera, onFinished]);
    return null;
};

// Re-linking the new hook into EditorContent

const EditorContent: React.FC = () => {
  const { 
    shapes, 
    tool, 
    selectedIds, 
    selectShape, 
    updateShapes,
    guideLines,
    currentView,
    setCurrentView
  } = useApp();

  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [isShapeDragging, setIsShapeDragging] = useState(false);
  const [isGizmoDragging, setIsGizmoDragging] = useState(false); 

  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => {
    shapeRefs.current[id] = ref;
  }, []);

  const { 
    ppState, 
    handlePointerHover: handlePPHover, 
    handlePointerDown: handlePPDown, 
    tempShape: ppTempShape 
  } = usePushPullManager();

  const {
      rotateState,
      handleRotateMove,
      handleClick: handleRotateClick
  } = useRotateManager();

  const { 
    drawPoints, 
    cursorPos: drawCursorPos, 
    setCursorPos: setDrawCursorPos, 
    snapInfo: drawSnapInfo, 
    setSnapInfo: setDrawSnapInfo, 
    isDragging: isDrawDragging, 
    handlePointerDown: handleDrawDown, 
    handlePointerUp: handleDrawUp, 
    handleClick: handleDrawClick, 
    typedInput,
    guideCreating,
    drawingNormal
  } = useDrawingManager();

  const isOrbitEnabled = 
    !isGizmoDragging && 
    ((tool === ToolType.SELECT && !isShapeDragging) ||
    (tool === ToolType.PUSH_PULL && !ppState.dragStartPoint) ||
    (tool === ToolType.ROTATE && rotateState.phase !== 'rotating') ||
    (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE && !isDrawDragging));

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight 
          position={[10, 20, 10]} 
          intensity={1.2} 
          castShadow 
          shadow-mapSize={[2048, 2048]} 
        />

        <Grid 
          infiniteGrid 
          fadeDistance={50} 
          sectionColor="#cbd5e1" 
          cellColor="#e2e8f0" 
          sectionSize={1} 
          cellSize={0.1} 
        />

        <MemoizedOrbitControls enabled={isOrbitEnabled} />

        <group 
            onPointerDown={(e) => {
                if (tool === ToolType.ROTATE) {
                    handleRotateClick(e);
                } else if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) {
                    handleDrawDown(e);
                } else {
                    selectShape('', false);
                }
            }} 
            onPointerUp={(e) => {
                 if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) handleDrawUp(e);
            }}
            onPointerMove={(e) => {
                 if (tool === ToolType.PUSH_PULL) handlePPHover(e);
                 if (tool === ToolType.ROTATE) handleRotateMove(e); 
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} /> 
            </mesh>
        </group>

        <group>
          {shapes.map(shape => {
            // Render temp shape if dragging side in push/pull
            const displayShape = (ppTempShape && ppTempShape.id === shape.id) ? ppTempShape : shape;

            return (
            <ShapeRenderer
              key={displayShape.id}
              shape={displayShape}
              isSelected={selectedIds.includes(displayShape.id)}
              onSelect={(e) => {
                e.stopPropagation();
                const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey;
                selectShape(displayShape.id, isMulti);
              }}
              pushPullState={ppState}
              pushPullHandlers={{
                handlePointerDown: handlePPDown,
                handlePointerHover: handlePPHover // Hover only
              }}
              drawingHandlers={{
                handlePointerDown: handleDrawDown,
                handlePointerUp: handleDrawUp,
                handleClick: handleDrawClick
              }}
              rotateHandlers={{
                  handleClick: handleRotateClick,
                  handlePointerMove: handleRotateMove
              }}
              setDraggingState={setIsShapeDragging}
              setShapeRef={(ref) => setShapeRef(displayShape.id, ref)}
              shapeRefs={shapeRefs}
              setAlignmentLines={setAlignmentLines}
            />
          )})}
        </group>

        <InteractionLayer
          shapes={shapes}
          tool={tool}
          setCursorPos={setDrawCursorPos}
          setSnapInfo={setDrawSnapInfo}
          cursorPos={drawCursorPos}
          snapInfo={drawSnapInfo}
          drawPoints={drawPoints}
          isDragging={isDrawDragging}
          drawingHeight={0}
          typedInput={typedInput}
          guideCreating={guideCreating}
          rotateState={rotateState}
          drawingNormal={drawingNormal}
        />

        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />
        <SelectionGizmo setDragging={setIsGizmoDragging} />

        <GizmoHelper alignment="bottom-left" margin={[80, 80]}>
          <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
        </GizmoHelper>
        <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />
    </>
  );
};

