import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3;
const ALIGN_THRESHOLD = 0.3;
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

type PushPullMode = 'extrusion' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface RotateState {
    phase: 'hover' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    axis: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentVector: THREE.Vector3 | null;
    currentAngle: number;
    initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }>;
    lockedAxis: THREE.Vector3 | null;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerHover: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    rotateHandlers: {
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    setShapeRef: (ref: THREE.Group | null) => void; 
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

const getShapeBounds = (shape: IShape) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    // Simple bounds based on points in local space (ignoring rotation for basic snap, improved later if needed)
    shape.points.forEach(p => {
         const wp = transformPoint(p, shape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });
    return {
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2
    };
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
};

const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= -EPSILON && u <= 1 + EPSILON && v >= -EPSILON && v <= 1 + EPSILON) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection { point: IPoint; edgeIndex: number; dist: number; }
    const intersections: Intersection[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);
        if (hit) {
            const isDuplicate = intersections.some(intr => Math.abs(intr.point.x - hit.x) < 0.001 && Math.abs(intr.point.z - hit.z) < 0.001);
            if (!isDuplicate) {
                const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }
    if (intersections.length < 2) return null;
    intersections.sort((a, b) => a.dist - b.dist);
    const [startHit, endHit] = intersections;
    const getVerticesBetween = (idx1: number, idx2: number) => {
        const verts: IPoint[] = [];
        let i = (idx1 + 1) % polyPoints.length;
        while (i !== (idx2 + 1) % polyPoints.length) {
            verts.push(polyPoints[i]);
            i = (i + 1) % polyPoints.length;
        }
        return verts;
    };
    const polyA_verts = getVerticesBetween(startHit.edgeIndex, endHit.edgeIndex);
    const polyA = [startHit.point, ...polyA_verts, endHit.point];
    const polyB_verts = getVerticesBetween(endHit.edgeIndex, startHit.edgeIndex);
    const polyB = [endHit.point, ...polyB_verts, startHit.point];
    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;
    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => { if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x; });
    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];
    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const euler = new THREE.Euler(...shape.rotation);
    const quat = new THREE.Quaternion().setFromEuler(euler);
    const left = new THREE.Vector3(-scaledHalfLen, 0, 0).applyQuaternion(quat);
    const right = new THREE.Vector3(scaledHalfLen, 0, 0).applyQuaternion(quat);
    return [pos.clone().add(left), pos.clone().add(right)];
};

const fragmentSegments = (segments: { start: IPoint; end: IPoint }[]): { start: IPoint; end: IPoint }[] => {
    let currentSegments = [...segments];
    let hasIntersections = true;
    let iterations = 0;
    while (hasIntersections && iterations < 50) {
        hasIntersections = false;
        iterations++;
        const newSegments: { start: IPoint; end: IPoint }[] = [];
        const processed = new Set<number>();
        for (let i = 0; i < currentSegments.length; i++) {
            if (processed.has(i)) continue;
            let s1 = currentSegments[i];
            let broken = false;
            for (let j = i + 1; j < currentSegments.length; j++) {
                if (processed.has(j)) continue;
                let s2 = currentSegments[j];
                const intersection = getSegmentIntersection(s1.start, s1.end, s2.start, s2.end);
                const isEndpoint = (p: IPoint, s: {start: IPoint, end: IPoint}) => (Math.abs(p.x - s.start.x) < 0.001 && Math.abs(p.z - s.start.z) < 0.001) || (Math.abs(p.x - s.end.x) < 0.001 && Math.abs(p.z - s.end.z) < 0.001);
                if (intersection && !isEndpoint(intersection, s1) && !isEndpoint(intersection, s2)) {
                    newSegments.push({ start: s1.start, end: intersection });
                    newSegments.push({ start: intersection, end: s1.end });
                    newSegments.push({ start: s2.start, end: intersection });
                    newSegments.push({ start: intersection, end: s2.end });
                    processed.add(i); processed.add(j);
                    broken = true; hasIntersections = true; break; 
                }
            }
            if (!broken) newSegments.push(s1);
        }
        if (hasIntersections) currentSegments = newSegments;
    }
    return currentSegments;
};

const getBoundingCenter = (points: IPoint[]) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
    return { x: (minX + maxX) / 2, z: (minZ + maxZ) / 2 };
};

const getGeometrySnap = (cursorPos: THREE.Vector3, ray: THREE.Ray, shapes: IShape[], activePoints: IPoint[] = [], threshold: number, intersectedObject?: THREE.Intersection): SnapResult => {
    let fallbackSnap: SnapResult;
    const getShapeUserData = (obj: THREE.Object3D) => obj.userData?.isShape ? obj.userData : obj.parent?.userData?.isShape ? obj.parent.userData : null;
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }
        fallbackSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id, normal };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid', distance: Infinity, normal: new THREE.Vector3(0, 1, 0)
        };
    }

    let bestVertexSnap: SnapResult | null = null;
    let bestEdgeSnap: SnapResult | null = null;
    let minVertexDist = threshold;
    let minEdgeDist = threshold;

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
            minVertexDist = dist;
        }
    }

    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 const edgeVec = new THREE.Vector3().subVectors(endpoints[1], endpoints[0]).normalize();
                 for(const ep of endpoints) {
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id, normal: edgeVec };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);
            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(shape.points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    }

    if (!bestVertexSnap || bestVertexSnap.distance > 0.1) {
        for (const shape of shapes) {
            const pts = shape.points;
            const len = pts.length;
            const currentH = shape.height * shape.scale[1];
            const hasHeight = Math.abs(currentH) > 0.001;
            const getWorldPos = (localX: number, localY: number, localZ: number) => {
                 const v = new THREE.Vector3(localX, localY, localZ);
                 v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
                 v.applyEuler(new THREE.Euler(...shape.rotation));
                 v.add(new THREE.Vector3(...shape.position));
                 return v;
            }
            for (let i = 0; i < len; i++) {
                const p1 = getWorldPos(pts[i].x, 0, pts[i].z);
                const p2 = getWorldPos(pts[(i + 1) % len].x, 0, pts[(i + 1) % len].z);
                const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                    const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                    const distMid = ray.distanceToPoint(mid);
                    const edgeVec = new THREE.Vector3().subVectors(v2, v1).normalize();
                    if (distMid < minEdgeDist) {
                        bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                        minEdgeDist = distMid;
                    }
                    const pointOnSegment = new THREE.Vector3();
                    const distSq = ray.distanceSqToSegment(v1, v2, undefined, pointOnSegment);
                    const distEdge = Math.sqrt(distSq);
                    if (distEdge < minEdgeDist) {
                         if (bestEdgeSnap?.type === 'midpoint' && bestEdgeSnap.distance < distEdge + 0.1) {} 
                         else {
                             bestEdgeSnap = { position: pointOnSegment, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                             minEdgeDist = distEdge;
                         }
                    }
                };
                checkSegment(p1, p2);
                if (hasHeight) {
                    const p1Top = getWorldPos(pts[i].x, shape.height, pts[i].z);
                    const p2Top = getWorldPos(pts[(i + 1) % len].x, shape.height, pts[(i + 1) % len].z);
                    checkSegment(p1Top, p2Top);
                    checkSegment(p1, p1Top);
                }
            }
        }
    }

    if (bestVertexSnap && bestEdgeSnap) return bestVertexSnap.distance < bestEdgeSnap.distance * 1.5 ? bestVertexSnap : bestEdgeSnap;
    if (bestVertexSnap) return bestVertexSnap;
    if (bestEdgeSnap) return bestEdgeSnap;
    return fallbackSnap;
};

// ... Render Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => new THREE.BufferGeometry().setFromPoints(points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)))), [points]);
    useLayoutEffect(() => { if (dashed && ref.current) ref.current.computeLineDistances(); }, [geometry, dashed]);
    return <line ref={ref} geometry={geometry}>{dashed ? <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> : <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />}</line>;
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return <group renderOrder={9999}>{lines.map((line) => <SimpleLine key={line.id} points={[line.points[0], line.points[1]]} color="#a855f7" dashed lineWidth={1} depthTest={false} opacity={0.8} />)}</group>;
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return <group>{lines.map((line, i) => <SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />)}</group>;
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b', size = 0.08, geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; }
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; }
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; }
    else if (type === 'face') color = '#3b82f6';

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments>
                 </mesh>
            ) : (<mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh>)}
            {type === 'edge' && snapEdge && <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />}
            {type === 'midpoint' && snapEdge && <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />}
        </group>
    );
};

const Protractor: React.FC<{ position: THREE.Vector3; axis: THREE.Vector3; startVector?: THREE.Vector3; currentVector?: THREE.Vector3; angle?: number; active: boolean; }> = ({ position, axis, startVector, currentVector, angle = 0, active }) => {
    let color = 'black';
    if (Math.abs(axis.y) > 0.9) color = '#3b82f6'; else if (Math.abs(axis.x) > 0.9) color = '#ef4444'; else if (Math.abs(axis.z) > 0.9) color = '#22c55e';
    const quaternion = useMemo(() => new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), axis.clone().normalize()), [axis]);
    const sectorRotation = useMemo(() => {
        if (!startVector) return new THREE.Euler(-Math.PI/2, 0, 0);
        const localStart = startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize();
        const angleOffset = Math.atan2(localStart.z, localStart.x);
        let finalStartAngle = -angleOffset;
        if (angle < 0) finalStartAngle = -angleOffset - Math.abs(angle);
        return new THREE.Euler(-Math.PI/2, 0, finalStartAngle);
    }, [startVector, quaternion, angle]);

    return (
        <group position={position} quaternion={quaternion}>
            <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[0.85, 0.9, 64]} /><meshBasicMaterial color={color} opacity={0.8} transparent side={THREE.DoubleSide} /></mesh>
            <mesh rotation={[-Math.PI/2, 0, 0]}><circleGeometry args={[0.85, 64]} /><meshBasicMaterial color={color} opacity={0.1} transparent side={THREE.DoubleSide} /></mesh>
            {Array.from({length: 24}).map((_, i) => (
                <group key={i} rotation={[0, (i * Math.PI * 2) / 24, 0]}>
                    <SimpleLine points={[new THREE.Vector3(0,0,0.85 - (i % 6 === 0 ? 0.2 : 0.1)), new THREE.Vector3(0,0,0.85)]} color={color} opacity={i % 6 === 0 ? 1 : 0.5} />
                </group>
            ))}
            {active && startVector && Math.abs(angle) > 0.01 && (
                 <mesh rotation={sectorRotation}><circleGeometry args={[0.85, 32, 0, Math.abs(angle)]} /><meshBasicMaterial color={color} opacity={0.3} transparent side={THREE.DoubleSide} /></mesh>
            )}
            {startVector && <SimpleLine points={[new THREE.Vector3(0,0,0), startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="black" lineWidth={2} />}
            {active && currentVector && <SimpleLine points={[new THREE.Vector3(0,0,0), currentVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="red" lineWidth={2} dashed />}
            {active && Math.abs(angle) > 0.01 && (
                <Billboard position={[0, 0.5, 0]}><Text fontSize={0.3} color="white" outlineWidth={0.02} outlineColor={color} backgroundColor="rgba(0,0,0,0.5)" padding={0.05}>{(angle * 180 / Math.PI).toFixed(1)}°</Text></Billboard>
            )}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const length = p1.distanceTo(p2);
    const color = isSelected ? '#3b82f6' : '#333';

    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(length)}</Text></Billboard>
        </group>
    );
};

const ShapeRenderer: React.FC<ShapeRendererProps> = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, setShapeRef, shapeRefs, setAlignmentLines }) => {
    const { layers, tool } = useApp();
    const meshRef = useRef<THREE.Group>(null);
    const parentLayer = layers.find(l => l.id === shape.layerId);

    useLayoutEffect(() => {
        if (setShapeRef && meshRef.current) setShapeRef(meshRef.current);
    }, [setShapeRef]);

    if (parentLayer && !parentLayer.visible) return null;
    if (shape.type === 'dimension') return <DimensionShape shape={shape} isSelected={isSelected} onSelect={(e) => { if (!isSelected) onSelect(e); }} />;

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);
    const isDraggingTop = pushPullState.mode === 'extrusion' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) scaleY = pushPullState.dragHeight / shape.height;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={meshRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            onClick={(e) => {
                if (tool === ToolType.SELECT) onSelect(e);
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
            }}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool !== ToolType.SELECT && tool !== ToolType.ROTATE) drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerHover(e);
                else if (tool === ToolType.ROTATE) rotateHandlers.handlePointerMove(e);
            }}
            onPointerUp={(e) => {
                if (!isPushPullMode && tool !== ToolType.SELECT && tool !== ToolType.ROTATE) drawingHandlers.handlePointerUp(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={highlightColor} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                <Edges color="#333" threshold={15} renderOrder={1000} visible={!isPushPullMode} />
            </mesh>
        </group>
    );
});

// --- Drawing Preview & Interaction Layer ---

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: any; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, guideCreating, drawingNormal }) => {
    const { formatValue } = useApp();
    if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
        const p1 = guideCreating.edge[0], p2 = guideCreating.edge[1];
        const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
        const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
        const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
        const edgeVec = new THREE.Vector3().subVectors(p2, p1);
        const pointVec = new THREE.Vector3().subVectors(guideCreating.current, p1);
        const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
        const dist = guideCreating.current.distanceTo(projected);
        return (
            <group>
                <SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} />
                <Billboard position={[guideCreating.current.x, guideCreating.current.y + 0.2, guideCreating.current.z]}><Text fontSize={0.25} color="#a855f7" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(dist)}</Text></Billboard>
            </group>
        );
    }
    if (points.length === 0) return null;
    const startVec = new THREE.Vector3(points[0].x, points[0].y, points[0].z);

    if (tool === ToolType.DRAW_LINE) {
        return <SimpleLine points={[...points.map(p => new THREE.Vector3(p.x, p.y, p.z)), cursorPos]} color="black" dashed />;
    }
    if (tool === ToolType.DRAW_RECT) {
        const normal = drawingNormal.clone().normalize();
        let up = new THREE.Vector3(0, 1, 0);
        if (Math.abs(normal.dot(up)) > 0.99) up.set(0, 0, 1);
        const right = new THREE.Vector3().crossVectors(normal, up).normalize();
        const top = new THREE.Vector3().crossVectors(right, normal).normalize();
        const diff = new THREE.Vector3().subVectors(cursorPos, startVec);
        const w = diff.dot(right), h = diff.dot(top);
        const p2 = startVec.clone().add(right.clone().multiplyScalar(w));
        const p3 = startVec.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startVec.clone().add(top.clone().multiplyScalar(h));
        return <SimpleLine points={[startVec, p2, p3, p4, startVec]} color="black" dashed />;
    }
    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(cursorPos);
        const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), drawingNormal);
        const circlePoints: THREE.Vector3[] = [];
        for (let i = 0; i <= 32; i++) {
            const theta = (i / 32) * Math.PI * 2;
            const localP = new THREE.Vector3(Math.cos(theta) * radius, 0, Math.sin(theta) * radius);
            localP.applyQuaternion(quaternion).add(startVec);
            circlePoints.push(localP);
        }
        return <><SimpleLine points={circlePoints} color="black" dashed /><SimpleLine points={[startVec, cursorPos]} color="gray" dashed opacity={0.5} /></>;
    }
    if (tool === ToolType.MEASURE) {
        if (points.length === 1) return <><SimpleLine points={[startVec, cursorPos]} color="blue" dashed /><mesh position={startVec}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh><mesh position={cursorPos}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh></>;
        if (points.length === 2) {
            const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);
            const v12 = new THREE.Vector3().subVectors(p2, startVec);
            const v13 = new THREE.Vector3().subVectors(cursorPos, startVec);
            const projection = v13.dot(v12) / v12.lengthSq();
            const projectedPoint = startVec.clone().add(v12.multiplyScalar(projection));
            const offsetVector = new THREE.Vector3().subVectors(cursorPos, projectedPoint);
            const dimStart = startVec.clone().add(offsetVector);
            const dimEnd = p2.clone().add(offsetVector);
            const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
            return (
                <group>
                    <SimpleLine points={[dimStart, dimEnd]} color="blue" />
                    <SimpleLine points={[startVec, dimStart]} color="gray" dashed />
                    <SimpleLine points={[p2, dimEnd]} color="gray" dashed />
                    <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color="blue" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(startVec.distanceTo(p2))}</Text></Billboard>
                </group>
            );
        }
    }
    return null;
};

const InteractionLayer: React.FC<{ shapes: IShape[]; tool: ToolType; setCursorPos: (v: THREE.Vector3) => void; setSnapInfo: (s: SnapResult | null) => void; cursorPos: THREE.Vector3; snapInfo: SnapResult | null; drawPoints: IPoint[]; isDragging: boolean; typedInput: string; guideCreating: any; rotateState: RotateState; drawingNormal: THREE.Vector3 }> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, typedInput, guideCreating, rotateState, drawingNormal }) => {
    const { layers, setMeasurement, formatValue } = useApp();
    const updateMeasurement = useCallback((pos: THREE.Vector3) => {
        let text = '';
        if (tool === ToolType.MEASURE && guideCreating.active) { /* ... */ }
        else if (tool === ToolType.ROTATE) {
             text = rotateState.phase === 'rotating' ? `角度: ${(rotateState.currentAngle * 180 / Math.PI).toFixed(1)}°` : (rotateState.lockedAxis ? '軸向鎖定' : '選擇中心');
        } else if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1];
            const dist = Math.sqrt((pos.x - start.x)**2 + (pos.y - start.y)**2 + (pos.z - start.z)**2);
            text = `${formatValue(dist)}`;
        } else if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) {
            text = `X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
        }
        if (typedInput) text += ` | ${typedInput}`;
        setMeasurement(text);
    }, [tool, drawPoints, guideCreating, rotateState, typedInput, setMeasurement, formatValue]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (isDragging && drawPoints.length > 0) {
            const startPoint = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(drawingNormal, startPoint);
            const target = new THREE.Vector3();
            if (e.ray.intersectPlane(plane, target)) {
                setCursorPos(target);
                setSnapInfo(null);
                updateMeasurement(target);
                return;
            }
        }
        const visibleShapes = shapes.filter(s => { const l = layers.find(ly => ly.id === s.layerId); return l ? l.visible : true; });
        const snap = getGeometrySnap(e.point, e.ray, visibleShapes, drawPoints, SNAP_THRESHOLD);
        setCursorPos(snap.position);
        setSnapInfo(snap);
        updateMeasurement(snap.position);
    }, [tool, shapes, layers, drawPoints, isDragging, drawingNormal, setCursorPos, setSnapInfo, updateMeasurement]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, 0.005, 0]} onPointerMove={onPointerMove} visible={false}><planeGeometry args={[1000, 1000]} /></mesh>
            {snapInfo && tool !== ToolType.ROTATE && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {tool === ToolType.ROTATE && <Protractor position={rotateState.pivot || (snapInfo ? snapInfo.position : cursorPos)} axis={rotateState.axis || (snapInfo?.normal || new THREE.Vector3(0,1,0))} startVector={rotateState.startVector} currentVector={rotateState.currentVector} angle={rotateState.currentAngle} active={rotateState.phase === 'rotating' || rotateState.phase === 'set-start'} />}
            <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} drawingNormal={drawingNormal} />
        </group>
    );
};

// ... Managers ...

const useRotateManager = () => {
    const { tool, selectedIds, shapes, updateShapes, setMeasurement } = useApp();
    const [lockedAxis, setLockedAxis] = useState<THREE.Vector3 | null>(null);
    const [rotateState, setRotateState] = useState<RotateState>({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });

    useEffect(() => {
        setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
        setLockedAxis(null);
    }, [tool]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (tool !== ToolType.ROTATE) return;
            let newAxis: THREE.Vector3 | null = null;
            if (e.key === 'ArrowRight') newAxis = new THREE.Vector3(1, 0, 0);
            else if (e.key === 'ArrowLeft') newAxis = new THREE.Vector3(0, 0, 1);
            else if (e.key === 'ArrowUp') newAxis = new THREE.Vector3(0, 1, 0);
            else if (e.key === 'ArrowDown') newAxis = null;
            if (newAxis || e.key === 'ArrowDown') {
                setLockedAxis(newAxis);
                setRotateState(prev => ({ ...prev, lockedAxis: newAxis, axis: (prev.phase === 'hover' && newAxis) ? newAxis : prev.axis }));
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (rotateState.phase !== 'rotating' || !rotateState.pivot || !rotateState.axis || !rotateState.startVector) return;
        const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(rotateState.axis, rotateState.pivot);
        const target = new THREE.Vector3();
        let hit = e.ray.intersectPlane(plane, target);
        if (!hit) { target.copy(e.point); plane.projectPoint(e.point, target); }
        const currentVec = target.sub(rotateState.pivot);
        if (currentVec.lengthSq() < 0.0001) return;
        let angle = rotateState.startVector.angleTo(currentVec);
        const cross = new THREE.Vector3().crossVectors(rotateState.startVector, currentVec);
        if (cross.dot(rotateState.axis) < 0) angle = -angle;
        const snapIncrement = 15 * (Math.PI / 180);
        if (Math.abs(angle - Math.round(angle / snapIncrement) * snapIncrement) < 0.087) angle = Math.round(angle / snapIncrement) * snapIncrement;
        setRotateState(prev => ({ ...prev, currentAngle: angle, currentVector: currentVec }));
        setMeasurement(`角度: ${(angle * 180 / Math.PI).toFixed(1)}°`);
        const updates = [];
        const qRot = new THREE.Quaternion().setFromAxisAngle(rotateState.axis, angle);
        for (const [id, init] of Object.entries(rotateState.initialTransforms)) {
            const newPos = init.pos.clone().sub(rotateState.pivot!).applyQuaternion(qRot).add(rotateState.pivot!);
            const newEuler = new THREE.Euler().setFromQuaternion(qRot.clone().multiply(init.quat));
            updates.push({ id, changes: { position: [newPos.x, newPos.y, newPos.z], rotation: [newEuler.x, newEuler.y, newEuler.z] } });
        }
        updateShapes(updates);
    }, [rotateState, updateShapes, setMeasurement]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE || selectedIds.length === 0) return;
        if (rotateState.phase === 'hover') {
            let axis = lockedAxis ? lockedAxis.clone() : (e.face ? e.face.normal.clone().applyMatrix3(new THREE.Matrix3().getNormalMatrix(e.object.matrixWorld)).normalize() : new THREE.Vector3(0, 1, 0));
            if (!lockedAxis) { if (Math.abs(axis.y) > 0.9) axis.set(0, 1, 0); else if (Math.abs(axis.x) > 0.9) axis.set(Math.sign(axis.x), 0, 0); else if (Math.abs(axis.z) > 0.9) axis.set(0, 0, Math.sign(axis.z)); }
            setRotateState({ phase: 'set-start', pivot: e.point.clone(), axis, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis });
            setMeasurement('點擊設定起始參考線');
        } else if (rotateState.phase === 'set-start') {
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(rotateState.axis!, rotateState.pivot!);
            const projectedStart = new THREE.Vector3();
            plane.projectPoint(e.point, projectedStart);
            const startVec = projectedStart.sub(rotateState.pivot!);
            if (startVec.lengthSq() < 0.0001) return;
            const initials: Record<string, any> = {};
            selectedIds.forEach(id => { const shape = shapes.find(s => s.id === id); if(shape) initials[id] = { pos: new THREE.Vector3(...shape.position), quat: new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)) }; });
            setRotateState(prev => ({ ...prev, phase: 'rotating', startVector: startVec, currentVector: startVec.clone(), initialTransforms: initials }));
        } else if (rotateState.phase === 'rotating') {
            setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
            setLockedAxis(null);
            setMeasurement('');
        }
    }, [tool, selectedIds, rotateState, shapes, setMeasurement, lockedAxis]);
    return { rotateState, handleRotateMove, handleClick };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, setTool, replaceShapes, setMeasurement, activeLayerId, addGuideLine } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [typedInput, setTypedInput] = useState('');
    const [drawingNormal, setDrawingNormal] = useState<THREE.Vector3>(new THREE.Vector3(0, 1, 0));
    const [guideCreation, setGuideCreation] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });

    useEffect(() => {
        setDrawPoints([]); setSnapInfo(null); setIsDragging(false); setMeasurement(''); setTypedInput(''); setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setDrawingNormal(new THREE.Vector3(0, 1, 0));
    }, [tool, setMeasurement]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        const normal = drawingNormal.clone().normalize();
        const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), normal);
        const euler = new THREE.Euler().setFromQuaternion(quaternion);
        const startPoint = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
        const inverseQuaternion = quaternion.clone().invert();

        let newShapePoints: IPoint[] = [];
        let newShapeBase: Partial<IShape> = { height: DEFAULT_HEIGHT, color: FLAT_COLOR, rotation: [euler.x, euler.y, euler.z], scale: [1, 1, 1], layerId: activeLayerId };

        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const startVec = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
             const endVec = new THREE.Vector3(finalPoints[finalPoints.length - 1].x, finalPoints[finalPoints.length - 1].y, finalPoints[finalPoints.length - 1].z);
             const localEnd = endVec.sub(startVec).applyQuaternion(inverseQuaternion);
             const width = localEnd.x, depth = localEnd.z;
             if (Math.abs(width) >= 0.01 && Math.abs(depth) >= 0.01) {
                 const halfW = Math.abs(width) / 2, halfD = Math.abs(depth) / 2;
                 const localCenter = new THREE.Vector3(width/2, 0, depth/2);
                 const worldCenter = localCenter.clone().applyQuaternion(quaternion).add(startVec);
                 newShapePoints = [{ x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD }];
                 newShapeBase = { ...newShapeBase, id: `rect-${Date.now()}`, type: 'flat', name: '矩形', position: [worldCenter.x, worldCenter.y, worldCenter.z] };
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const startVec = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
            const radius = startVec.distanceTo(new THREE.Vector3(finalPoints[1].x, finalPoints[1].y, finalPoints[1].z));
            if (radius > 0.01) {
                newShapePoints = createCirclePoints(radius);
                newShapeBase = { ...newShapeBase, id: `circle-${Date.now()}`, type: 'flat', name: '圓形', position: [startVec.x, startVec.y, startVec.z] };
            }
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 3) {
            addShape({ ...newShapeBase, id: `dim-${Date.now()}`, type: 'dimension', name: '尺寸標註', points: finalPoints, position: [0,0,0] } as IShape);
            setDrawPoints([]); setTool(ToolType.SELECT); return;
        }

        let cuttingSegments = [];
        if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0], end = finalPoints[finalPoints.length - 1]; 
             if (Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2 + (end.y - start.y)**2) >= 0.01) cuttingSegments.push({ start, end });
        } else if (newShapePoints.length > 0 && newShapeBase.position && Math.abs(normal.y) > 0.9) {
            const pos = newShapeBase.position as [number, number, number];
            for(let i=0; i<newShapePoints.length-1; i++) cuttingSegments.push({ start: { x: newShapePoints[i].x + pos[0], y: 0, z: newShapePoints[i].z + pos[2] }, end: { x: newShapePoints[i+1].x + pos[0], y: 0, z: newShapePoints[i+1].z + pos[2] } });
        }

        let cutOccurred = false;
        const shapesToAddList: IShape[] = [];
        const idsToRemove = new Set<string>();

        if (cuttingSegments.length > 0 && Math.abs(normal.y) > 0.9) {
            let workingShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
            let fragments: IShape[] = [];
            for (const seg of cuttingSegments) {
                const currentCandidates = [...workingShapes.filter(s => !idsToRemove.has(s.id)), ...fragments];
                for (const shape of currentCandidates) {
                    if (shape.points.length <= 2) continue;
                    const worldPoints = shape.points.map(p => { const vec = transformPoint(p, shape); return { x: vec.x, y: vec.y, z: vec.z }; });
                    const splitResult = cutPolygonBySegment(worldPoints, seg.start, seg.end);
                    if (splitResult) {
                        if (shapes.find(s => s.id === shape.id)) idsToRemove.add(shape.id); else fragments = fragments.filter(f => f.id !== shape.id);
                        const makeFrag = (pts: IPoint[]) => {
                             const c = getBoundingCenter(pts);
                             return { ...shape, id: `split-${Date.now()}-${Math.random()}`, points: pts.map(p => ({ x: p.x - c.x, y: 0, z: p.z - c.z })), position: [c.x, shape.position[1], c.z], rotation: [0,0,0] } as IShape;
                        };
                        fragments.push(makeFrag(splitResult[0]), makeFrag(splitResult[1]));
                        cutOccurred = true;
                    }
                }
            }
            if (cutOccurred) shapesToAddList.push(...fragments);

            const edgesToProcess: any[] = [...cuttingSegments];
            shapes.forEach(shape => { if (shape.name === 'Edge' && !idsToRemove.has(shape.id)) { const eps = getLineEndpoints(shape); if(eps) edgesToProcess.push({ start: {x: eps[0].x, y: 0, z: eps[0].z}, end: {x: eps[1].x, y: 0, z: eps[1].z}, originalId: shape.id }); }});
            const fragmented = fragmentSegments(edgesToProcess);
            fragmented.forEach(seg => {
                const dx = seg.end.x - seg.start.x, dz = seg.end.z - seg.start.z;
                const len = Math.sqrt(dx*dx + dz*dz);
                if(len < 0.001) return;
                const angle = Math.atan2(dz, dx), cx = (seg.start.x + seg.end.x) / 2, cz = (seg.start.z + seg.end.z) / 2;
                shapesToAddList.push({ ...newShapeBase, id: `edge-${Date.now()}-${Math.random()}`, type: 'flat', name: 'Edge', points: [{x:-len/2,y:0,z:-0.01},{x:len/2,y:0,z:-0.01},{x:len/2,y:0,z:0.01},{x:-len/2,y:0,z:0.01}], height: 0.005, color: '#334155', position: [cx, 0, cz], rotation: [0, -angle, 0] } as IShape);
            });
            edgesToProcess.forEach(e => { if(e.originalId) idsToRemove.add(e.originalId); });
            cutOccurred = true;
        }

        if (cutOccurred) replaceShapes(Array.from(idsToRemove), shapesToAddList);
        else if (newShapePoints.length > 0) addShape({ ...newShapeBase, points: newShapePoints } as IShape);
        else if (tool === ToolType.DRAW_LINE && cuttingSegments.length > 0) {
             const seg = cuttingSegments[0];
             const p1 = new THREE.Vector3(seg.start.x, seg.start.y, seg.start.z), p2 = new THREE.Vector3(seg.end.x, seg.end.y, seg.end.z);
             const center = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
             const len = p1.distanceTo(p2);
             const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
             const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(1, 0, 0), direction);
             const e = new THREE.Euler().setFromQuaternion(q);
             addShape({ ...newShapeBase, id: `edge-${Date.now()}`, type: 'flat', name: 'Edge', points: [{x:-len/2,y:0,z:-0.01},{x:len/2,y:0,z:-0.01},{x:len/2,y:0,z:0.01},{x:-len/2,y:0,z:0.01}], height: 0.005, color: '#334155', position: [center.x, center.y, center.z], rotation: [e.x, e.y, e.z] } as IShape);
        }

        if (tool === ToolType.DRAW_LINE) setDrawPoints([{ x: finalPoints[finalPoints.length-1].x, y: finalPoints[finalPoints.length-1].y, z: finalPoints[finalPoints.length-1].z }]);
        else { setDrawPoints([]); setTool(ToolType.SELECT); }
    }, [tool, addShape, replaceShapes, activeLayerId, drawingNormal, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE || e.button !== 0) return;
        e.stopPropagation(); setTypedInput('');
        const pt = snapInfo ? snapInfo.position.clone() : e.point.clone();
        setCursorPos(pt.clone());
        if (drawPoints.length === 0) {
            setDrawingNormal(snapInfo?.normal ? snapInfo.normal.clone() : new THREE.Vector3(0, 1, 0));
            setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]);
            if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        } else {
            if (tool === ToolType.DRAW_LINE || tool === ToolType.MEASURE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        }
        if (tool === ToolType.MEASURE && snapInfo && snapInfo.type === 'edge' && snapInfo.snapEdge) {
            setIsDragging(true); setGuideCreation({ active: true, start: pt.clone(), current: pt.clone(), edge: snapInfo.snapEdge }); return;
        }
        setIsDragging(true);
    }, [tool, drawPoints, snapInfo]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        setIsDragging(false);
        if (tool === ToolType.MEASURE && guideCreation.active && guideCreation.edge) {
            const p1 = guideCreation.edge[0], p2 = guideCreation.edge[1];
            const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
            const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
            const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
            addGuideLine({ id: `guide-${Date.now()}`, points: [[lineStart.x, lineStart.y, lineStart.z], [lineEnd.x, lineEnd.y, lineEnd.z]] });
            setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); return;
        }
        if (tool === ToolType.MEASURE) { if (drawPoints.length >= 3) finishShape(drawPoints); return; }
        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_LINE) && drawPoints.length >= 2) {
             const points = [...drawPoints]; points[points.length-1] = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z }; finishShape(points);
        }
    }, [tool, drawPoints, cursorPos, finishShape, guideCreation, addGuideLine]);

    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;
        const start = drawPoints[drawPoints.length - 1];
        const startVec = new THREE.Vector3(start.x, start.y, start.z);
        let targetVec = new THREE.Vector3();
        const direction = cursorPos.clone().sub(startVec).normalize();
        if (direction.lengthSq() < 0.0001) direction.set(1, 0, 0);

        if (tool === ToolType.DRAW_RECT) {
             const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat);
             if (parts.length > 0 && !parts.some(isNaN)) targetVec = startVec.clone().add(direction.multiplyScalar(parts[0]));
        } else {
             const val = parseFloat(typedInput);
             if (!isNaN(val)) targetVec = startVec.clone().add(direction.multiplyScalar(val));
        }
        const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }];
        finishShape(finalPoints);
    }, [typedInput, drawPoints, cursorPos, tool, finishShape]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             if ([ToolType.SELECT, ToolType.PUSH_PULL, ToolType.ROTATE].includes(tool)) return;
             if (e.key === 'Escape') { setDrawPoints([]); setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setTool(ToolType.SELECT); setMeasurement(''); setTypedInput(''); setDrawingNormal(new THREE.Vector3(0, 1, 0)); return; }
             if (drawPoints.length === 0) return; 
             if (e.key === 'Enter') { handleInputSubmit(); return; }
             if (e.key === 'Backspace') { setTypedInput(prev => prev.slice(0, -1)); return; }
             if (/^[0-9.,-]$/.test(e.key)) { setTypedInput(prev => prev + e.key); }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit, setTool, setMeasurement]);

    useEffect(() => {
        if (guideCreation.active) setGuideCreation(prev => ({ ...prev, current: cursorPos.clone() }));
    }, [cursorPos, guideCreation.active]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, handlePointerDown, handlePointerUp, handleClick: () => {}, typedInput, guideCreating, drawingNormal };
};

// ... OrbitControls ...
const MemoizedOrbitControls = React.memo(({ enabled }: { enabled: boolean }) => <OrbitControls makeDefault enabled={enabled} minDistance={2} maxDistance={50} dampingFactor={0.1} rotateSpeed={0.5} panSpeed={0.5} zoomSpeed={0.6} />);

// ... SelectionGizmo & CameraHandler ...
const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) { if (targetObj) setTargetObj(null); return; }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => { if (found) return; if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) found = child; });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return <TransformControls object={targetObj} mode={transformMode} space={transformMode === 'scale' ? 'local' : 'world'} makeDefault onDraggingChange={(isDragging) => { setDragging(isDragging); const controls = (camera as any).controls; if(controls) controls.enabled = !isDragging; }} onMouseUp={() => { if (targetObj) updateShape(selectedId!, { position: [targetObj.position.x, targetObj.position.y, targetObj.position.z], rotation: [targetObj.rotation.x, targetObj.rotation.y, targetObj.rotation.z], scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z] }); }} />;
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;
        switch (view) {
            case 'top': targetPos.set(0, DISTANCE, 0); break;
            case 'bottom': targetPos.set(0, -DISTANCE, 0); break;
            case 'front': targetPos.set(0, 0, DISTANCE); break;
            case 'back': targetPos.set(0, 0, -DISTANCE); break;
            case 'right': targetPos.set(DISTANCE, 0, 0); break;
            case 'left': targetPos.set(-DISTANCE, 0, 0); break;
            default: return;
        }
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) { const c = controls as any; if (c.target && typeof c.target.set === 'function') { c.target.set(0, 0, 0); c.update(); } }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

