const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: any; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, guideCreating, drawingNormal }) => {
    const { formatValue } = useApp();
    if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
        const p1 = guideCreating.edge[0], p2 = guideCreating.edge[1];
        const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
        const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
        const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
        const edgeVec = new THREE.Vector3().subVectors(p2, p1);
        const pointVec = new THREE.Vector3().subVectors(guideCreating.current, p1);
        const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
        const dist = guideCreating.current.distanceTo(projected);
        return (
            <group>
                <SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} />
                <Billboard position={[guideCreating.current.x, guideCreating.current.y + 0.2, guideCreating.current.z]}><Text fontSize={0.25} color="#a855f7" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(dist)}</Text></Billboard>
            </group>
        );
    }
    if (points.length === 0) return null;
    const startVec = new THREE.Vector3(points[0].x, points[0].y, points[0].z);

    if (tool === ToolType.DRAW_LINE) {
        return <SimpleLine points={[...points.map(p => new THREE.Vector3(p.x, p.y, p.z)), cursorPos]} color="black" dashed />;
    }
    if (tool === ToolType.DRAW_RECT) {
        const normal = drawingNormal.clone().normalize();
        let up = new THREE.Vector3(0, 1, 0);
        if (Math.abs(normal.dot(up)) > 0.99) up.set(0, 0, 1);
        const right = new THREE.Vector3().crossVectors(normal, up).normalize();
        const top = new THREE.Vector3().crossVectors(right, normal).normalize();
        const diff = new THREE.Vector3().subVectors(cursorPos, startVec);
        const w = diff.dot(right), h = diff.dot(top);
        const p2 = startVec.clone().add(right.clone().multiplyScalar(w));
        const p3 = startVec.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startVec.clone().add(top.clone().multiplyScalar(h));
        return <SimpleLine points={[startVec, p2, p3, p4, startVec]} color="black" dashed />;
    }
    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(cursorPos);
        const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), drawingNormal);
        const circlePoints: THREE.Vector3[] = [];
        for (let i = 0; i <= 32; i++) {
            const theta = (i / 32) * Math.PI * 2;
            const localP = new THREE.Vector3(Math.cos(theta) * radius, 0, Math.sin(theta) * radius);
            localP.applyQuaternion(quaternion).add(startVec);
            circlePoints.push(localP);
        }
        return <><SimpleLine points={circlePoints} color="black" dashed /><SimpleLine points={[startVec, cursorPos]} color="gray" dashed opacity={0.5} /></>;
    }
    if (tool === ToolType.MEASURE) {
        if (points.length === 1) return <><SimpleLine points={[startVec, cursorPos]} color="blue" dashed /><mesh position={startVec}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh><mesh position={cursorPos}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh></>;
        if (points.length === 2) {
            const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);
            const v12 = new THREE.Vector3().subVectors(p2, startVec);
            const v13 = new THREE.Vector3().subVectors(cursorPos, startVec);
            const projection = v13.dot(v12) / v12.lengthSq();
            const projectedPoint = startVec.clone().add(v12.multiplyScalar(projection));
            const offsetVector = new THREE.Vector3().subVectors(cursorPos, projectedPoint);
            const dimStart = startVec.clone().add(offsetVector);
            const dimEnd = p2.clone().add(offsetVector);
            const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
            return (
                <group>
                    <SimpleLine points={[dimStart, dimEnd]} color="blue" />
                    <SimpleLine points={[startVec, dimStart]} color="gray" dashed />
                    <SimpleLine points={[p2, dimEnd]} color="gray" dashed />
                    <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color="blue" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(startVec.distanceTo(p2))}</Text></Billboard>
                </group>
            );
        }
    }
    return null;
};

const InteractionLayer: React.FC<{ shapes: IShape[]; tool: ToolType; setCursorPos: (v: THREE.Vector3) => void; setSnapInfo: (s: SnapResult | null) => void; cursorPos: THREE.Vector3; snapInfo: SnapResult | null; drawPoints: IPoint[]; isDragging: boolean; typedInput: string; guideCreating: any; rotateState: RotateState; drawingNormal: THREE.Vector3 }> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, typedInput, guideCreating, rotateState, drawingNormal }) => {
    const { layers, setMeasurement, formatValue } = useApp();
    const updateMeasurement = useCallback((pos: THREE.Vector3) => {
        let text = '';
        if (tool === ToolType.MEASURE && guideCreating.active) { /* ... */ }
        else if (tool === ToolType.ROTATE) {
             text = rotateState.phase === 'rotating' ? `角度: ${(rotateState.currentAngle * 180 / Math.PI).toFixed(1)}°` : (rotateState.lockedAxis ? '軸向鎖定' : '選擇中心');
        } else if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1];
            const dist = Math.sqrt((pos.x - start.x)**2 + (pos.y - start.y)**2 + (pos.z - start.z)**2);
            text = `${formatValue(dist)}`;
        } else if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) {
            text = `X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
        }
        if (typedInput) text += ` | ${typedInput}`;
        setMeasurement(text);
    }, [tool, drawPoints, guideCreating, rotateState, typedInput, setMeasurement, formatValue]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (isDragging && drawPoints.length > 0) {
            const startPoint = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(drawingNormal, startPoint);
            const target = new THREE.Vector3();
            if (e.ray.intersectPlane(plane, target)) {
                setCursorPos(target);
                setSnapInfo(null);
                updateMeasurement(target);
                return;
            }
        }
        const visibleShapes = shapes.filter(s => { const l = layers.find(ly => ly.id === s.layerId); return l ? l.visible : true; });
        const snap = getGeometrySnap(e.point, e.ray, visibleShapes, drawPoints, SNAP_THRESHOLD);
        setCursorPos(snap.position);
        setSnapInfo(snap);
        updateMeasurement(snap.position);
    }, [tool, shapes, layers, drawPoints, isDragging, drawingNormal, setCursorPos, setSnapInfo, updateMeasurement]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, 0.005, 0]} onPointerMove={onPointerMove} visible={false}><planeGeometry args={[1000, 1000]} /></mesh>
            {snapInfo && tool !== ToolType.ROTATE && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {tool === ToolType.ROTATE && <Protractor position={rotateState.pivot || (snapInfo ? snapInfo.position : cursorPos)} axis={rotateState.axis || (snapInfo?.normal || new THREE.Vector3(0,1,0))} startVector={rotateState.startVector} currentVector={rotateState.currentVector} angle={rotateState.currentAngle} active={rotateState.phase === 'rotating' || rotateState.phase === 'set-start'} />}
            <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} drawingNormal={drawingNormal} />
        </group>
    );
};

