const useRotateManager = () => {
    const { tool, selectedIds, shapes, updateShapes, setMeasurement } = useApp();
    const [lockedAxis, setLockedAxis] = useState<THREE.Vector3 | null>(null);
    const [rotateState, setRotateState] = useState<RotateState>({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });

    useEffect(() => {
        setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
        setLockedAxis(null);
    }, [tool]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (tool !== ToolType.ROTATE) return;
            let newAxis: THREE.Vector3 | null = null;
            if (e.key === 'ArrowRight') newAxis = new THREE.Vector3(1, 0, 0);
            else if (e.key === 'ArrowLeft') newAxis = new THREE.Vector3(0, 0, 1);
            else if (e.key === 'ArrowUp') newAxis = new THREE.Vector3(0, 1, 0);
            else if (e.key === 'ArrowDown') newAxis = null;
            if (newAxis || e.key === 'ArrowDown') {
                setLockedAxis(newAxis);
                setRotateState(prev => ({ ...prev, lockedAxis: newAxis, axis: (prev.phase === 'hover' && newAxis) ? newAxis : prev.axis }));
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (rotateState.phase !== 'rotating' || !rotateState.pivot || !rotateState.axis || !rotateState.startVector) return;
        const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(rotateState.axis, rotateState.pivot);
        const target = new THREE.Vector3();
        let hit = e.ray.intersectPlane(plane, target);
        if (!hit) { target.copy(e.point); plane.projectPoint(e.point, target); }
        const currentVec = target.sub(rotateState.pivot);
        if (currentVec.lengthSq() < 0.0001) return;
        let angle = rotateState.startVector.angleTo(currentVec);
        const cross = new THREE.Vector3().crossVectors(rotateState.startVector, currentVec);
        if (cross.dot(rotateState.axis) < 0) angle = -angle;
        const snapIncrement = 15 * (Math.PI / 180);
        if (Math.abs(angle - Math.round(angle / snapIncrement) * snapIncrement) < 0.087) angle = Math.round(angle / snapIncrement) * snapIncrement;
        setRotateState(prev => ({ ...prev, currentAngle: angle, currentVector: currentVec }));
        setMeasurement(`角度: ${(angle * 180 / Math.PI).toFixed(1)}°`);
        const updates = [];
        const qRot = new THREE.Quaternion().setFromAxisAngle(rotateState.axis, angle);
        for (const [id, init] of Object.entries(rotateState.initialTransforms)) {
            const typedInit = init as { pos: THREE.Vector3, quat: THREE.Quaternion };
            const newPos = typedInit.pos.clone().sub(rotateState.pivot!).applyQuaternion(qRot).add(rotateState.pivot!);
            const newEuler = new THREE.Euler().setFromQuaternion(qRot.clone().multiply(typedInit.quat));
            updates.push({ id, changes: { position: [newPos.x, newPos.y, newPos.z], rotation: [newEuler.x, newEuler.y, newEuler.z] } });
        }
        updateShapes(updates);
    }, [rotateState, updateShapes, setMeasurement]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE || selectedIds.length === 0) return;
        if (rotateState.phase === 'hover') {
            let axis = lockedAxis ? lockedAxis.clone() : (e.face ? e.face.normal.clone().applyMatrix3(new THREE.Matrix3().getNormalMatrix(e.object.matrixWorld)).normalize() : new THREE.Vector3(0, 1, 0));
            if (!lockedAxis) { if (Math.abs(axis.y) > 0.9) axis.set(0, 1, 0); else if (Math.abs(axis.x) > 0.9) axis.set(Math.sign(axis.x), 0, 0); else if (Math.abs(axis.z) > 0.9) axis.set(0, 0, Math.sign(axis.z)); }
            setRotateState({ phase: 'set-start', pivot: e.point.clone(), axis, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis });
            setMeasurement('點擊設定起始參考線');
        } else if (rotateState.phase === 'set-start') {
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(rotateState.axis!, rotateState.pivot!);
            const projectedStart = new THREE.Vector3();
            plane.projectPoint(e.point, projectedStart);
            const startVec = projectedStart.sub(rotateState.pivot!);
            if (startVec.lengthSq() < 0.0001) return;
            const initials: Record<string, any> = {};
            selectedIds.forEach(id => { const shape = shapes.find(s => s.id === id); if(shape) initials[id] = { pos: new THREE.Vector3(...shape.position), quat: new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)) }; });
            setRotateState(prev => ({ ...prev, phase: 'rotating', startVector: startVec, currentVector: startVec.clone(), initialTransforms: initials }));
        } else if (rotateState.phase === 'rotating') {
            setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
            setLockedAxis(null);
            setMeasurement('');
        }
    }, [tool, selectedIds, rotateState, shapes, setMeasurement, lockedAxis]);
    return { rotateState, handleRotateMove, handleClick };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, setTool, replaceShapes, setMeasurement, activeLayerId, addGuideLine } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [typedInput, setTypedInput] = useState('');
    const [drawingNormal, setDrawingNormal] = useState<THREE.Vector3>(new THREE.Vector3(0, 1, 0));
    const [guideCreating, setGuideCreating] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });

    useEffect(() => {
        setDrawPoints([]); setSnapInfo(null); setIsDragging(false); setMeasurement(''); setTypedInput(''); setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setDrawingNormal(new THREE.Vector3(0, 1, 0));
    }, [tool, setMeasurement]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        const normal = drawingNormal.clone().normalize();
        const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), normal);
        const euler = new THREE.Euler().setFromQuaternion(quaternion);
        const startPoint = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
        const inverseQuaternion = quaternion.clone().invert();

        let newShapePoints: IPoint[] = [];
        let newShapeBase: Partial<IShape> = { height: DEFAULT_HEIGHT, color: FLAT_COLOR, rotation: [euler.x, euler.y, euler.z], scale: [1, 1, 1], layerId: activeLayerId };

        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const startVec = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
             const endVec = new THREE.Vector3(finalPoints[finalPoints.length - 1].x, finalPoints[finalPoints.length - 1].y, finalPoints[finalPoints.length - 1].z);
             const localEnd = endVec.sub(startVec).applyQuaternion(inverseQuaternion);
             const width = localEnd.x, depth = localEnd.z;
             if (Math.abs(width) >= 0.01 && Math.abs(depth) >= 0.01) {
                 const halfW = Math.abs(width) / 2, halfD = Math.abs(depth) / 2;
                 const localCenter = new THREE.Vector3(width/2, 0, depth/2);
                 const worldCenter = localCenter.clone().applyQuaternion(quaternion).add(startVec);
                 newShapePoints = [{ x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD }];
                 newShapeBase = { ...newShapeBase, id: `rect-${Date.now()}`, type: 'flat', name: '矩形', position: [worldCenter.x, worldCenter.y, worldCenter.z] };
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const startVec = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
            const radius = startVec.distanceTo(new THREE.Vector3(finalPoints[1].x, finalPoints[1].y, finalPoints[1].z));
            if (radius > 0.01) {
                newShapePoints = createCirclePoints(radius);
                newShapeBase = { ...newShapeBase, id: `circle-${Date.now()}`, type: 'flat', name: '圓形', position: [startVec.x, startVec.y, startVec.z] };
            }
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 3) {
            addShape({ ...newShapeBase, id: `dim-${Date.now()}`, type: 'dimension', name: '尺寸標註', points: finalPoints, position: [0,0,0] } as IShape);
            setDrawPoints([]); setTool(ToolType.SELECT); return;
        }

        let cuttingSegments = [];
        if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0], end = finalPoints[finalPoints.length - 1]; 
             if (Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2 + (end.y - start.y)**2) >= 0.01) cuttingSegments.push({ start, end });
        } else if (newShapePoints.length > 0 && newShapeBase.position && Math.abs(normal.y) > 0.9) {
            const pos = newShapeBase.position as [number, number, number];
            for(let i=0; i<newShapePoints.length-1; i++) cuttingSegments.push({ start: { x: newShapePoints[i].x + pos[0], y: 0, z: newShapePoints[i].z + pos[2] }, end: { x: newShapePoints[i+1].x + pos[0], y: 0, z: newShapePoints[i+1].z + pos[2] } });
        }

        let cutOccurred = false;
        const shapesToAddList: IShape[] = [];
        const idsToRemove = new Set<string>();

        if (cuttingSegments.length > 0 && Math.abs(normal.y) > 0.9) {
            let workingShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
            let fragments: IShape[] = [];
            for (const seg of cuttingSegments) {
                const currentCandidates = [...workingShapes.filter(s => !idsToRemove.has(s.id)), ...fragments];
                for (const shape of currentCandidates) {
                    if (shape.points.length <= 2) continue;
                    const worldPoints = shape.points.map(p => { const vec = transformPoint(p, shape); return { x: vec.x, y: vec.y, z: vec.z }; });
                    const splitResult = cutPolygonBySegment(worldPoints, seg.start, seg.end);
                    if (splitResult) {
                        if (shapes.find(s => s.id === shape.id)) idsToRemove.add(shape.id); else fragments = fragments.filter(f => f.id !== shape.id);
                        const makeFrag = (pts: IPoint[]) => {
                             const c = getBoundingCenter(pts);
                             return { ...shape, id: `split-${Date.now()}-${Math.random()}`, points: pts.map(p => ({ x: p.x - c.x, y: 0, z: p.z - c.z })), position: [c.x, shape.position[1], c.z], rotation: [0,0,0] } as IShape;
                        };
                        fragments.push(makeFrag(splitResult[0]), makeFrag(splitResult[1]));
                        cutOccurred = true;
                    }
                }
            }
            if (cutOccurred) shapesToAddList.push(...fragments);

            const edgesToProcess: any[] = [...cuttingSegments];
            shapes.forEach(shape => { if (shape.name === 'Edge' && !idsToRemove.has(shape.id)) { const eps = getLineEndpoints(shape); if(eps) edgesToProcess.push({ start: {x: eps[0].x, y: 0, z: eps[0].z}, end: {x: eps[1].x, y: 0, z: eps[1].z}, originalId: shape.id }); }});
            const fragmented = fragmentSegments(edgesToProcess);
            fragmented.forEach(seg => {
                const dx = seg.end.x - seg.start.x, dz = seg.end.z - seg.start.z;
                const len = Math.sqrt(dx*dx + dz*dz);
                if(len < 0.001) return;
                const angle = Math.atan2(dz, dx), cx = (seg.start.x + seg.end.x) / 2, cz = (seg.start.z + seg.end.z) / 2;
                shapesToAddList.push({ ...newShapeBase, id: `edge-${Date.now()}-${Math.random()}`, type: 'flat', name: 'Edge', points: [{x:-len/2,y:0,z:-0.01},{x:len/2,y:0,z:-0.01},{x:len/2,y:0,z:0.01},{x:-len/2,y:0,z:0.01}], height: 0.005, color: '#334155', position: [cx, 0, cz], rotation: [0, -angle, 0] } as IShape);
            });
            edgesToProcess.forEach(e => { if(e.originalId) idsToRemove.add(e.originalId); });
            cutOccurred = true;
        }

        if (cutOccurred) replaceShapes(Array.from(idsToRemove), shapesToAddList);
        else if (newShapePoints.length > 0) addShape({ ...newShapeBase, points: newShapePoints } as IShape);
        else if (tool === ToolType.DRAW_LINE && cuttingSegments.length > 0) {
             const seg = cuttingSegments[0];
             const p1 = new THREE.Vector3(seg.start.x, seg.start.y, seg.start.z), p2 = new THREE.Vector3(seg.end.x, seg.end.y, seg.end.z);
             const center = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
             const len = p1.distanceTo(p2);
             const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
             const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(1, 0, 0), direction);
             const e = new THREE.Euler().setFromQuaternion(q);
             addShape({ ...newShapeBase, id: `edge-${Date.now()}`, type: 'flat', name: 'Edge', points: [{x:-len/2,y:0,z:-0.01},{x:len/2,y:0,z:-0.01},{x:len/2,y:0,z:0.01},{x:-len/2,y:0,z:0.01}], height: 0.005, color: '#334155', position: [center.x, center.y, center.z], rotation: [e.x, e.y, e.z] } as IShape);
        }

        if (tool === ToolType.DRAW_LINE) setDrawPoints([{ x: finalPoints[finalPoints.length-1].x, y: finalPoints[finalPoints.length-1].y, z: finalPoints[finalPoints.length-1].z }]);
        else { setDrawPoints([]); setTool(ToolType.SELECT); }
    }, [tool, addShape, replaceShapes, activeLayerId, drawingNormal, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE || e.button !== 0) return;
        e.stopPropagation(); setTypedInput('');
        const pt = snapInfo ? snapInfo.position.clone() : e.point.clone();
        setCursorPos(pt.clone());
        if (drawPoints.length === 0) {
            setDrawingNormal(snapInfo?.normal ? snapInfo.normal.clone() : new THREE.Vector3(0, 1, 0));
            setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]);
            if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        } else {
            if (tool === ToolType.DRAW_LINE || tool === ToolType.MEASURE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        }
        if (tool === ToolType.MEASURE && snapInfo && snapInfo.type === 'edge' && snapInfo.snapEdge) {
            setIsDragging(true); setGuideCreating({ active: true, start: pt.clone(), current: pt.clone(), edge: snapInfo.snapEdge }); return;
        }
        setIsDragging(true);
    }, [tool, drawPoints, snapInfo]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        setIsDragging(false);
        if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
            const p1 = guideCreating.edge[0], p2 = guideCreating.edge[1];
            const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
            const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
            const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
            addGuideLine({ id: `guide-${Date.now()}`, points: [[lineStart.x, lineStart.y, lineStart.z], [lineEnd.x, lineEnd.y, lineEnd.z]] });
            setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); return;
        }
        if (tool === ToolType.MEASURE) { if (drawPoints.length >= 3) finishShape(drawPoints); return; }
        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_LINE) && drawPoints.length >= 2) {
             const points = [...drawPoints]; points[points.length-1] = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z }; finishShape(points);
        }
    }, [tool, drawPoints, cursorPos, finishShape, guideCreating, addGuideLine]);

    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;
        const start = drawPoints[drawPoints.length - 1];
        const startVec = new THREE.Vector3(start.x, start.y, start.z);
        let targetVec = new THREE.Vector3();
        const direction = cursorPos.clone().sub(startVec).normalize();
        if (direction.lengthSq() < 0.0001) direction.set(1, 0, 0);

        if (tool === ToolType.DRAW_RECT) {
             const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat);
             if (parts.length > 0 && !parts.some(isNaN)) targetVec = startVec.clone().add(direction.multiplyScalar(parts[0]));
        } else {
             const val = parseFloat(typedInput);
             if (!isNaN(val)) targetVec = startVec.clone().add(direction.multiplyScalar(val));
        }
        const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }];
        finishShape(finalPoints);
    }, [typedInput, drawPoints, cursorPos, tool, finishShape]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             if ([ToolType.SELECT, ToolType.PUSH_PULL, ToolType.ROTATE].includes(tool)) return;
             if (e.key === 'Escape') { setDrawPoints([]); setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setTool(ToolType.SELECT); setMeasurement(''); setTypedInput(''); setDrawingNormal(new THREE.Vector3(0, 1, 0)); return; }
             if (drawPoints.length === 0) return; 
             if (e.key === 'Enter') { handleInputSubmit(); return; }
             if (e.key === 'Backspace') { setTypedInput(prev => prev.slice(0, -1)); return; }
             if (/^[0-9.,-]$/.test(e.key)) { setTypedInput(prev => prev + e.key); }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit, setTool, setMeasurement]);

    useEffect(() => {
        if (guideCreating.active) setGuideCreating(prev => ({ ...prev, current: cursorPos.clone() }));
    }, [cursorPos, guideCreating.active]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, handlePointerDown, handlePointerUp, handleClick: () => {}, typedInput, guideCreating, drawingNormal };
};

const usePushPullManager = () => {
    const { tool, shapes, updateShape, setMeasurement, formatValue } = useApp();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0)
    });
    const [tempShape, setTempShape] = useState<IShape | null>(null);

    useEffect(() => {
        if (tool !== ToolType.PUSH_PULL) {
            setPPState({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0) });
            setTempShape(null);
            setMeasurement('');
            document.body.style.cursor = 'default';
        }
    }, [tool, setMeasurement]);

    const handlePointerHover = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        // Dragging Logic
        if (ppState.dragStartPoint && ppState.hoveredShapeId) {
             const start = ppState.dragStartPoint;
             // Intersect a vertical plane passing through dragStartPoint and facing camera
             const planeNormal = new THREE.Vector3().subVectors(e.camera.position, start).setY(0).normalize();
             const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, start);
             const target = new THREE.Vector3();
             e.ray.intersectPlane(plane, target);

             const heightDiff = target.y - start.y;
             const newHeight = Math.max(0.01, ppState.originalHeight + heightDiff);

             setPPState(prev => ({ ...prev, dragHeight: newHeight }));
             if (tempShape) setTempShape({ ...tempShape, height: newHeight });

             setMeasurement(`高度: ${formatValue(newHeight)}`);
             return;
        }

        // Hover Logic
        // We only care about top face for extrusion in this simple version
        // We need to check if we are hitting a shape
        const object = e.object;
        const shapeData = object.userData;

        if (shapeData?.isShape) {
            e.stopPropagation();
            if (e.face && e.face.normal.y > 0.9) {
                 setPPState(prev => ({ 
                     ...prev, 
                     mode: 'extrusion', 
                     hoveredShapeId: shapeData.id, 
                     normal: new THREE.Vector3(0, 1, 0)
                 }));
                 document.body.style.cursor = 'ns-resize';
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        } else {
             setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
             document.body.style.cursor = 'default';
        }
    }, [tool, ppState, shapes, tempShape, setMeasurement, formatValue]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return;
        if (ppState.mode === 'extrusion' && ppState.hoveredShapeId) {
            e.stopPropagation();
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (shape) {
                setPPState(prev => ({
                    ...prev,
                    dragStartPoint: e.point.clone(),
                    originalHeight: shape.height,
                    dragHeight: shape.height
                }));
                setTempShape(shape);
            }
        }
    }, [tool, ppState, shapes]);

    useEffect(() => {
        const handlePointerUp = () => {
            if (tool === ToolType.PUSH_PULL && ppState.dragStartPoint && ppState.hoveredShapeId && tempShape) {
                updateShape(ppState.hoveredShapeId, { height: tempShape.height });
                setPPState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
                setTempShape(null);
                setMeasurement('');
            }
        };
        window.addEventListener('pointerup', handlePointerUp);
        return () => window.removeEventListener('pointerup', handlePointerUp);
    }, [tool, ppState, tempShape, updateShape, setMeasurement]);

    return { ppState, handlePointerHover, handlePointerDown, tempShape };
};

// ... OrbitControls ...
const MemoizedOrbitControls = React.memo(({ enabled }: { enabled: boolean }) => <OrbitControls makeDefault enabled={enabled} minDistance={2} maxDistance={50} dampingFactor={0.1} rotateSpeed={0.5} panSpeed={0.5} zoomSpeed={0.6} />);

// ... SelectionGizmo & CameraHandler ...
const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) { if (targetObj) setTargetObj(null); return; }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => { if (found) return; if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) found = child; });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return <TransformControls object={targetObj} mode={transformMode} space={transformMode === 'scale' ? 'local' : 'world'} makeDefault onDraggingChange={(isDragging) => { setDragging(isDragging); const controls = (camera as any).controls; if(controls) controls.enabled = !isDragging; }} onMouseUp={() => { if (targetObj) updateShape(selectedId!, { position: [targetObj.position.x, targetObj.position.y, targetObj.position.z], rotation: [targetObj.rotation.x, targetObj.rotation.y, targetObj.rotation.z], scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z] }); }} />;
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;
        switch (view) {
            case 'top': targetPos.set(0, DISTANCE, 0); break;
            case 'bottom': targetPos.set(0, -DISTANCE, 0); break;
            case 'front': targetPos.set(0, 0, DISTANCE); break;
            case 'back': targetPos.set(0, 0, -DISTANCE); break;
            case 'right': targetPos.set(DISTANCE, 0, 0); break;
            case 'left': targetPos.set(-DISTANCE, 0, 0); break;
            default: return;
        }
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) { const c = controls as any; if (c.target && typeof c.target.set === 'function') { c.target.set(0, 0, 0); c.update(); } }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

