const Protractor: React.FC<{ 
    position: THREE.Vector3; 
    axis: THREE.Vector3; 
    startVector?: THREE.Vector3; 
    currentVector?: THREE.Vector3;
    angle?: number;
    active: boolean; 
}> = ({ position, axis, startVector, currentVector, angle = 0, active }) => {
    let color = 'black';
    if (Math.abs(axis.y) > 0.9) color = '#3b82f6';
    else if (Math.abs(axis.x) > 0.9) color = '#ef4444';
    else if (Math.abs(axis.z) > 0.9) color = '#22c55e';

    const quaternion = useMemo(() => {
        const q = new THREE.Quaternion();
        q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axis.clone().normalize());
        return q;
    }, [axis]);

    const sectorRotation = useMemo(() => {
        if (!startVector) return new THREE.Euler(-Math.PI/2, 0, 0);
        const localStart = startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize();
        const angleOffset = Math.atan2(localStart.z, localStart.x);
        let finalStartAngle = -angleOffset;
        if (angle < 0) {
             finalStartAngle = -angleOffset - Math.abs(angle);
        }
        return new THREE.Euler(-Math.PI/2, 0, finalStartAngle);
    }, [startVector, quaternion, angle]);

    return (
        <group position={position} quaternion={quaternion}>
            <mesh rotation={[-Math.PI/2, 0, 0]}>
                <ringGeometry args={[0.85, 0.9, 64]} />
                <meshBasicMaterial color={color} opacity={0.8} transparent side={THREE.DoubleSide} />
            </mesh>
            <mesh rotation={[-Math.PI/2, 0, 0]}>
                <circleGeometry args={[0.85, 64]} />
                <meshBasicMaterial color={color} opacity={0.1} transparent side={THREE.DoubleSide} />
            </mesh>
            {Array.from({length: 24}).map((_, i) => {
                const isMajor = i % 6 === 0;
                const len = isMajor ? 0.2 : 0.1;
                return (
                    <group key={i} rotation={[0, (i * Math.PI * 2) / 24, 0]}>
                        <SimpleLine points={[new THREE.Vector3(0,0,0.85 - len), new THREE.Vector3(0,0,0.85)]} color={color} opacity={isMajor ? 1 : 0.5} />
                    </group>
                )
            })}
            {active && startVector && Math.abs(angle) > 0.01 && (
                 <mesh rotation={sectorRotation}>
                    <circleGeometry args={[0.85, 32, 0, Math.abs(angle)]} />
                    <meshBasicMaterial color={color} opacity={0.3} transparent side={THREE.DoubleSide} />
                 </mesh>
            )}
            {startVector && (
                 <SimpleLine points={[new THREE.Vector3(0,0,0), startVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="black" lineWidth={2} />
            )}
            {active && currentVector && (
                 <SimpleLine points={[new THREE.Vector3(0,0,0), currentVector.clone().applyQuaternion(quaternion.clone().invert()).normalize().multiplyScalar(1.0)]} color="red" lineWidth={2} dashed />
            )}
            {active && Math.abs(angle) > 0.01 && (
                <Billboard position={[0, 0.5, 0]}>
                    <Text fontSize={0.3} color="white" outlineWidth={0.02} outlineColor={color} backgroundColor="rgba(0,0,0,0.5)" padding={0.05}>
                        {(angle * 180 / Math.PI).toFixed(1)}°
                    </Text>
                </Billboard>
            )}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const length = p1.distanceTo(p2);
    const color = isSelected ? '#3b82f6' : '#333';

    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(length)}</Text></Billboard>
        </group>
    );
};

