const usePushPullManager = () => {
    const { shapes, updateShape, tool } = useApp();
    const [ppState, setPpState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0,1,0)
    });
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        if (tool !== ToolType.PUSH_PULL) {
            setPpState({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0,1,0) });
            setIsDragging(false);
        }
    }, [tool]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging && ppState.dragStartPoint && ppState.hoveredShapeId) {
            e.stopPropagation();
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const plane = new THREE.Plane();
            plane.setFromNormalAndCoplanarPoint(e.camera.position.clone().sub(ppState.dragStartPoint).normalize(), ppState.dragStartPoint);

            const target = new THREE.Vector3();
            if (e.ray.intersectPlane(plane, target)) {
                const deltaY = target.y - ppState.dragStartPoint.y;
                const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                setPpState(prev => ({ ...prev, dragHeight: newHeight }));
            }
        } else {
            if (e.object.userData?.isShape) {
                const shapeId = e.object.userData.id;
                const shape = shapes.find(s => s.id === shapeId);
                if (!shape) return;

                const localY = e.point.y - shape.position[1];
                const isTop = Math.abs(localY - shape.height) < 0.1;

                if (isTop) {
                     setPpState(prev => ({ ...prev, mode: 'top', hoveredShapeId: shapeId, normal: new THREE.Vector3(0,1,0) }));
                     document.body.style.cursor = 'ns-resize';
                } else {
                    setPpState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                    document.body.style.cursor = 'default';
                }
            }
        }
    }, [tool, shapes, isDragging, ppState]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
         if (tool !== ToolType.PUSH_PULL) return;
         if (ppState.mode === 'top' && ppState.hoveredShapeId) {
             e.stopPropagation();
             setIsDragging(true);
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             setPpState(prev => ({ 
                 ...prev, 
                 dragStartPoint: e.point.clone(), 
                 originalHeight: shape ? shape.height : 0.01,
                 dragHeight: shape ? shape.height : 0.01
             }));
         }
    }, [tool, ppState.mode, ppState.hoveredShapeId, shapes]);

    const handlePointerUp = useCallback(() => {
         if (isDragging && ppState.hoveredShapeId && ppState.dragHeight !== undefined) {
             updateShape(ppState.hoveredShapeId, { height: ppState.dragHeight });
             setIsDragging(false);
             setPpState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
         }
    }, [isDragging, ppState, updateShape]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging };
};

