const CameraHandler = ({ view, onFinished }: { view: string | null; onFinished: () => void }) => {
  const { camera } = useThree();
  useEffect(() => {
    if (!view) return;
    const pos = new THREE.Vector3();
    const offset = 10;
    if (view === 'top') { pos.set(0, offset, 0); camera.lookAt(0, 0, 0); }
    if (view === 'front') { pos.set(0, 0, offset); camera.lookAt(0, 0, 0); }
    if (view === 'left') { pos.set(-offset, 0, 0); camera.lookAt(0, 0, 0); }
    if (view === 'right') { pos.set(offset, 0, 0); camera.lookAt(0, 0, 0); }
    if (view === 'bottom') { pos.set(0, -offset, 0); camera.lookAt(0, 0, 0); }
    camera.position.set(pos.x, pos.y, pos.z);
    onFinished();
  }, [view, camera, onFinished]);
  return null;
};

